import { existsSync } from 'node:fs';
import { createServer, type Server } from 'node:http';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import cors from 'cors';
import express, { type Express, type Router } from 'express';

import { authMiddleware, authRouter } from './auth.js';
import { ensureRuntimeDirectories, HOST, PORT } from './config.js';

interface Application {
  app: Express;
  httpServer: Server;
}

type RouterModule = Record<string, Router>;
type WebSocketModule = {
  attachWebSocket?: (server: Server) => void | Promise<void>;
};

const sourceDirectory = dirname(fileURLToPath(import.meta.url));

function optionalModulePath(relativePath: string): string | null {
  const basePath = resolve(sourceDirectory, relativePath);
  for (const extension of ['.ts', '.js']) {
    const candidate = `${basePath}${extension}`;
    if (existsSync(candidate)) return candidate;
  }
  return null;
}

async function mountOptionalRouter(
  app: Express,
  relativePath: string,
  exportName: string,
): Promise<void> {
  const modulePath = optionalModulePath(relativePath);
  if (!modulePath) return;
  const module = await import(pathToFileURL(modulePath).href) as RouterModule;
  const router = module[exportName];
  if (!router) throw new Error(`${relativePath} does not export ${exportName}`);
  app.use(router);
}

export async function createApplication(): Promise<Application> {
  await ensureRuntimeDirectories();
  const app = express();
  app.use(cors());
  app.use(express.json());
  app.get('/health', (_request, response) => {
    response.json({ ok: true });
  });
  app.use('/auth', authRouter);
  app.get('/me', authMiddleware, (request, response) => {
    response.json(request.user);
  });

  const httpServer = createServer(app);
  await mountOptionalRouter(app, './routes/chats', 'chatsRouter');
  await mountOptionalRouter(app, './routes/messages', 'messagesRouter');
  await mountOptionalRouter(app, './routes/media', 'mediaRouter');

  const webSocketPath = optionalModulePath('./ws');
  if (webSocketPath) {
    const module = await import(pathToFileURL(webSocketPath).href) as WebSocketModule;
    if (!module.attachWebSocket) throw new Error('./ws does not export attachWebSocket');
    await module.attachWebSocket(httpServer);
  }
  return { app, httpServer };
}

export async function startServer(): Promise<Server> {
  const { httpServer } = await createApplication();
  await new Promise<void>((resolveListening, reject) => {
    httpServer.once('error', reject);
    httpServer.listen(PORT, HOST, () => {
      httpServer.off('error', reject);
      resolveListening();
    });
  });
  return httpServer;
}

const entryPoint = process.argv[1] ? pathToFileURL(resolve(process.argv[1])).href : null;
if (entryPoint === import.meta.url) {
  startServer().catch((error: unknown) => {
    console.error(error);
    process.exitCode = 1;
  });
}
